'use strict';
(() => {
  const D=window.GeoRadarData,$=id=>document.getElementById(id);
  let records=[],warnings=[],filtered=[],map,page=0,popup;
  const section=document.querySelector('.empty-state');
  section.outerHTML='<div class="company-actions"><button id="company-import" class="outline">Datei / JSON übernehmen ↑</button><button id="company-export" class="subtle">Unternehmen exportieren ↓</button><button id="company-clear" class="subtle">Daten entfernen</button></div><div id="company-summary" class="micro" role="status">Keine Unternehmensdaten geladen.</div><div class="company-filters"><input id="company-search" type="search" aria-label="Unternehmen durchsuchen" placeholder="Firma, Ort oder PLZ …"><select id="company-status" aria-label="Kundenstatus"><option value="all">Alle Status</option><option value="existing">Bestandskunden</option><option value="prospect">Potenzielle Neukunden</option><option value="priority">Besonders interessant</option><option value="unknown">Status ungeklärt</option></select></div><div id="company-counts" class="company-counts"></div><div id="company-list" class="company-list"></div><div class="company-paging"><button id="company-prev" class="subtle">← Zurück</button><span id="company-page" class="micro"></span><button id="company-next" class="subtle">Weiter →</button></div><details id="company-warnings"><summary>Hinweise zur Standortqualität</summary><div id="company-warning-list"></div></details>';
  document.querySelector('.empty-count').id='company-total';
  const importDialog=document.createElement('dialog');importDialog.id='company-import-dialog';
  importDialog.innerHTML='<div class="dialog-top"><h2>Unternehmensdaten übernehmen</h2><button class="icon-button" id="company-import-close" aria-label="Import schließen">×</button></div><p>JSON, UTF-8-CSV/TSV oder Excel .xlsx auswählen oder JSON-Daten einfügen. Jede Übergabe ersetzt den bisherigen Bestand vollständig. Die Verarbeitung bleibt im Browser; keine automatische Speicherung oder Geocodierung.</p><label class="field-label" for="company-file">JSON, CSV oder Excel .xlsx (maximal 5 MB)</label><input id="company-file" type="file" accept="application/json,.json,.csv,.tsv,.xlsx"><label class="field-label" for="company-json">JSON mit records-Liste</label><textarea id="company-json" rows="12" spellcheck="false" placeholder=\'{"schema":"mangold-georadar/companies/v1","records":[]}\'></textarea><p class="micro">id, name und country sind Pflicht. status: existing, prospect, priority oder unknown. lon/lat sind optional. Zweistellige postalCode oder postalPrefix (z. B. 88) erscheinen ohne Koordinaten nur als grobe Gebietspunkte. Exakte Positionen nur mit geprüftem Nachweis als locationAccuracy: exact kennzeichnen.</p><pre id="company-import-feedback" role="status"></pre><button id="company-apply" class="outline">Daten prüfen und übernehmen</button>';
  document.body.append(importDialog);
  const importButton=$('company-import');importButton.onclick=()=>{ $('company-import-feedback').textContent='';importDialog.showModal();};
  $('company-import-close').onclick=()=>importDialog.close();
  let importSequence=0;$('company-file').onchange=async e=>{const sequence=++importSequence,f=e.target.files[0];if(!f)return;$('company-apply').disabled=true;$('company-json').value='';try{const payload=await GeoRadarImport.read(f);if(sequence!==importSequence)return;$('company-json').value=JSON.stringify(payload,null,2);$('company-import-feedback').textContent='Datei geprüft: '+payload.records.length+' Unternehmen. Excel nutzt das erste Tabellenblatt; Vertreterzuordnungen werden übernommen. Bitte übernehmen.';}catch(error){if(sequence!==importSequence)return;$('company-import-feedback').textContent='Nicht eingelesen: '+error.message;}finally{if(sequence===importSequence)$('company-apply').disabled=false;}};
  $('company-apply').onclick=()=>{try{const text=$('company-json').value;if(new Blob([text]).size>5*1024*1024)throw Error('Maximal 5 MB pro Übergabe.');accept(JSON.parse(text),'JSON-Import');importDialog.close();$('company-json').value='';$('company-file').value='';}catch(e){$('company-import-feedback').textContent='Nicht übernommen. Der bisherige Bestand bleibt erhalten.\n'+e.message;}};
  function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  $('company-export').onclick=()=>download('Mangold-GeoRadar-Unternehmen.json',window.GeoRadarCompanies.getSnapshot());
  $('company-clear').onclick=()=>accept({records:[]},'Bestand entfernt');
  for(const id of ['company-search','company-status'])$(id).addEventListener(id==='company-search'?'input':'change',()=>{page=0;render();});
  $('country').addEventListener('change',()=>{page=0;render();});
  document.querySelectorAll('[data-area]').forEach(b=>b.addEventListener('click',()=>{page=0;render();}));
  $('reset').addEventListener('click',()=>{page=0;render();});
  $('company-prev').onclick=()=>{page--;render();};$('company-next').onclick=()=>{page++;render();};
  const layer=document.createElement('label');layer.innerHTML='<span>Unternehmensstandorte<small>Gruppierte Marker · Statusfarben</small></span><input type="checkbox" id="company-layer" checked>'; $('layer-controls').append(layer);
  $('company-layer').onchange=()=>{if(!map)return;for(const id of ['company-clusters','company-cluster-count','company-points','company-prefix-label','territory-site-ring'])map.setLayoutProperty(id,'visibility',$('company-layer').checked?'visible':'none');};
  function accept(payload,source){const data=D.validate(payload);if(source==='JSON-Import'||source==='MCP-Datenübergabe'||source==='Bestand entfernt')delete window.GeoRadarResearchSource;records=data.records;warnings=data.warnings;if(data.territories)window.GeoRadarTerritories?.setConfiguration(data.territories);page=0;if(popup)popup.remove();render();$('company-summary').textContent=source+': '+records.length+' Unternehmen übernommen. Jede Übergabe ersetzt den Bestand.';document.dispatchEvent(new CustomEvent('georadar:companies-updated',{detail:D.summarize(records)}));}
  function render(){
    if(popup)popup.remove();
    const area=$('country').value,status=$('company-status').value,q=$('company-search').value.trim().toLocaleLowerCase('de');
    filtered=records.filter(r=>(area==='both'||r.country===(area==='de'?'Deutschland':'Österreich'))&&(status==='all'||r.status===status)&&(!q||[r.name,r.city,r.postalCode,r.postalPrefix,r.industry,r.type,r.address,r.formattedAddress].some(v=>String(v||'').toLocaleLowerCase('de').includes(q)))&&(!window.GeoRadarTerritories||window.GeoRadarTerritories.matches(r))&&(typeof window.GeoRadarExtraFilter!=='function'||window.GeoRadarExtraFilter(r)));
    const count=D.summarize(filtered);$('company-total').textContent=count.total;$('footer-data-count').textContent=count.total+' / '+records.length+' Unternehmen';
    $('company-counts').replaceChildren();for(const [key,item]of Object.entries(D.statuses)){const span=document.createElement('span'),dot=document.createElement('i');dot.className='dot';dot.style.background=item.color;span.append(dot,document.createTextNode(item.label+': '+count[key]));$('company-counts').append(span);}
    const maxPage=Math.max(0,Math.ceil(filtered.length/30)-1);page=Math.max(0,Math.min(page,maxPage));
    const list=$('company-list');list.replaceChildren();
    for(const r of filtered.slice(page*30,page*30+30)){const b=document.createElement('button'),title=document.createElement('b'),sub=document.createElement('small'),pos=D.position(r);title.textContent=r.name;sub.textContent=[r.type,D.postalLabel(r),r.city,r.country].filter(Boolean).join(' · ')+(pos?.isPrefix?' · grober Gebietspunkt, kein Firmenstandort':!pos?' · ohne Kartenposition':'');const assigned=GeoRadarRepresentatives.resolve(GeoRadarRepresentatives.assignment(r,window.GeoRadarTerritories?.getConfiguration()||[])[0]),suggestion=!window.GeoRadarTerritories?.representativeFor(r)?GeoRadarRepresentatives.suggest(r,window.GeoRadarTerritories?.getConfiguration()||[]):null;if(assigned){const badge=document.createElement('small');badge.textContent='Vertreter '+assigned.code+' '+assigned.personnelNumber;b.append(badge);}b.append(title,sub);if(suggestion){const hint=document.createElement('small');hint.className='representative-suggestion';hint.textContent='Fachlicher Vorschlag: '+GeoRadarRepresentatives.suggestions(r,window.GeoRadarTerritories?.getConfiguration()||[]).map(d=>d.label).join(', ')+' · keine Zuordnung';b.append(hint);}b.onclick=()=>show(r);list.append(b);}
    if(!filtered.length){const p=document.createElement('p');p.textContent=records.length?'Keine Unternehmen für diese Filter.':'Noch keine Unternehmensdaten. JSON importieren oder Daten aus einer MCP-App-Übergabe empfangen.';list.append(p);}
    $('company-page').textContent=filtered.length?(page+1)+' / '+(maxPage+1):'0 / 0';$('company-prev').disabled=page===0;$('company-next').disabled=page>=maxPage;
    $('company-warning-list').replaceChildren();const intro=document.createElement('p');intro.textContent=count.located+' von '+count.total+' mit Standortkoordinaten; '+count.prefixLocated+' nur als PLZ-Gebietspunkt; '+count.unlocated+' ohne Marker. Präfixpunkte sind schematisch, keine Firmenstandorte oder Gebietsgrenzen.';$('company-warning-list').append(intro);
    for(const message of warnings.slice(0,40)){const p=document.createElement('p');p.textContent=message;$('company-warning-list').append(p);}if(warnings.length>40){const p=document.createElement('p');p.textContent='Weitere Hinweise: '+(warnings.length-40);$('company-warning-list').append(p);}
    document.dispatchEvent(new CustomEvent('georadar:filter-updated'));
    if(map?.getSource('companies'))map.getSource('companies').setData({type:'FeatureCollection',features:filtered.map(r=>{const p=D.position(r);return p?{type:'Feature',geometry:{type:'Point',coordinates:p.coordinates},properties:{id:r.id,status:r.status,locationAccuracy:r.locationAccuracy,isPrefix:p.isPrefix,postalPrefix:p.prefix||'',repCode:window.GeoRadarTerritories?.representativeFor(r)||''}}:null;}).filter(Boolean)});
  }
  function show(r){
    const content=document.createElement('div'),title=document.createElement('h3');title.textContent=r.name;content.append(title);
    const pos=D.position(r),info={Typ:r.type,Status:D.statuses[r.status].label,Adresse:r.formattedAddress||r.address,Vertreter:[r.salesRep,r.personnelNumber].filter(Boolean).join(' · '),'Fachlicher Vorschlag':GeoRadarRepresentatives.suggestions(r,window.GeoRadarTerritories?.getConfiguration()||[]).map(d=>d.reason).join(' | '),Standort:[r.street,D.postalLabel(r),r.city,r.state,r.country].filter(Boolean).join(', '),Branche:r.industry,'Lead-Score':r.leadScore,Umsatz:r.revenue===undefined?undefined:new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(r.revenue),Potenzial:r.potential,Produktinteressen:r.product,Verflechtungen:r.relationships,Bemerkungen:r.notes,Koordinatenquelle:pos?.isPrefix?'GeoNames · gemittelte PLZ-Referenzpunkte (CC BY 4.0)':r.coordinateSource,Positionsgenauigkeit:pos?.isPrefix?'Nur zweistelliges PLZ-Präfix. Schematischer Gebietspunkt, kein Firmenstandort und keine Gebietsgrenze.':!pos?'Keine Koordinaten':({exact:'Als exakt übergeben · Quellenprüfung durch Datenlieferant',approximate:'Ungefähre Position, kein exakter Firmenstandort',unknown:'Genauigkeit ungeprüft, kein bestätigter Firmenstandort'})[r.locationAccuracy]};
    for(const [label,value]of Object.entries(info)){if(value===undefined||value==='')continue;const p=document.createElement('p'),b=document.createElement('b');b.textContent=label+': ';p.append(b,document.createTextNode(String(value)));content.append(p);}
    if(r.attributes&&Object.keys(r.attributes).length){const t=document.createElement('table');t.className='attribute-table';for(const [k,v]of Object.entries(r.attributes)){const tr=document.createElement('tr'),th=document.createElement('th'),td=document.createElement('td');th.textContent=k;td.textContent=typeof v==='boolean'?(v?'ja':'nein'):typeof v==='number'?v.toLocaleString('de-DE'):v;tr.append(th,td);t.append(tr);}content.append(t);}
    if(r.geocodeNote){const p=document.createElement('p');p.className='micro';p.textContent='Hinweis Standort: '+r.geocodeNote;content.append(p);}
    for(const [label,value]of [['Begründung',r.reason],['Gesprächsanlass',r.opportunity],['Prüfung',r.needsReview?'Zu prüfen':undefined],['Datentyp',r.isFictional?'Fiktiver Testdatensatz':undefined]])if(value){const p=document.createElement('p');p.textContent=label+': '+value;content.append(p);}
    for(const source of [...(r.website?[{url:r.website,title:'Unternehmenswebsite'}]:[]),...(r.sources||[])]){const p=document.createElement('p'),a=document.createElement('a');a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=source.title||source.url;p.append(a);content.append(p);}
    if(typeof window.GeoRadarPopupExtras==='function'){try{window.GeoRadarPopupExtras(r,content);}catch{}}
    if(map&&pos){if(popup)popup.remove();map.flyTo({center:pos.coordinates,zoom:pos.isPrefix?6:Math.max(map.getZoom(),11),duration:window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:700});popup=new maplibregl.Popup({maxWidth:'340px'}).setLngLat(pos.coordinates).setDOMContent(content).addTo(map);}
    else{const d=document.createElement('dialog'),close=document.createElement('button');close.className='outline';close.textContent='Schließen';close.onclick=()=>{d.close();d.remove();};d.append(content,close);document.body.append(d);d.showModal();}
  }
  document.addEventListener('georadar:map-ready',event=>{
    map=event.detail;
    map.addSource('companies',{type:'geojson',data:{type:'FeatureCollection',features:[]},cluster:true,clusterMaxZoom:13,clusterRadius:45});
    map.addLayer({id:'company-clusters',type:'circle',source:'companies',filter:['has','point_count'],paint:{'circle-color':'#324b61','circle-radius':['step',['get','point_count'],18,50,23,500,29],'circle-stroke-color':'#d3e4ef','circle-stroke-width':2}});
    map.addLayer({id:'company-cluster-count',type:'symbol',source:'companies',filter:['has','point_count'],layout:{'text-field':['get','point_count_abbreviated'],'text-font':['Noto Sans Bold'],'text-size':12},paint:{'text-color':'#ffffff'}});
    const statusColor=['match',['get','status'],'existing','#2387ec','prospect','#FFEA00','priority','#e0444e','#788592'];
    map.addLayer({id:'company-points',type:'circle',source:'companies',filter:['!', ['has','point_count']],paint:{'circle-color':statusColor,'circle-radius':['case',['==',['get','isPrefix'],true],13,8],'circle-opacity':['case',['==',['get','isPrefix'],true],.15,1],'circle-stroke-width':['case',['==',['get','locationAccuracy'],'exact'],2,3],'circle-stroke-color':['case',['==',['get','isPrefix'],true],statusColor,['==',['get','locationAccuracy'],'exact'],'#18384e','#b6c4ce']}});
    map.addLayer({id:'company-prefix-label',type:'symbol',source:'companies',filter:['all',['!',['has','point_count']],['==',['get','isPrefix'],true]],layout:{'text-field':['concat',['get','postalPrefix'],'…'],'text-font':['Noto Sans Bold'],'text-size':11,'text-offset':[0,2]},paint:{'text-color':'#173a55','text-halo-color':'#ffffff','text-halo-width':1.5}});
    map.on('click','company-clusters',async e=>{const f=e.features[0];try{const zoom=await map.getSource('companies').getClusterExpansionZoom(f.properties.cluster_id);map.easeTo({center:f.geometry.coordinates,zoom,duration:500});}catch{}});
    map.on('click','company-points',e=>{const r=records.find(r=>r.id===e.features[0].properties.id);if(r)show(r);});
    for(const id of ['company-points','company-clusters']){map.on('mouseenter',id,()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave',id,()=>map.getCanvas().style.cursor='');}
    render();
  });
  document.addEventListener('georadar:tool-result',e=>{try{if(e.detail?.isError)throw Error('Der MCP-Aufruf meldet einen Fehler. Der bisherige Bestand bleibt erhalten.');if(!e.detail?.structuredContent)throw Error('Keine strukturierten Unternehmensdaten empfangen.');accept(e.detail.structuredContent,'MCP-Datenübergabe');$('bridge-state').textContent='MCP · '+records.length+' Unternehmen empfangen';}catch(error){$('bridge-state').textContent='MCP-Daten nicht übernommen: '+error.message;}});
  document.addEventListener('georadar:territories-changed',()=>{page=0;render();});
  document.addEventListener('georadar:extra-filter-changed',()=>{page=0;render();});
  document.addEventListener('georadar:research-loaded',e=>{try{accept(e.detail.data,'Gespeicherte Recherche '+e.detail.code);}catch(error){$('bridge-state').textContent='Gespeicherte Daten nicht übernommen: '+error.message;}});
  window.GeoRadarCompanies={replace:(data,source='Gespeicherter Datenstand')=>accept(data,source),getFilteredRecords:()=>filtered.map(r=>({...r})),getSnapshot:()=>({schema:'mangold-georadar/companies/v1',records:records.map(r=>({...r})),...(window.GeoRadarTerritories?{territories:window.GeoRadarTerritories.getConfiguration()}: {})})};
  render();
})();
